; cost.asm -- chapter 10: one of each logic, bit, shift and rotate instruction
; generated by gen10.py
        INCLUDE "msx.inc"
        OUTPUT "cost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
init:   di
        ld sp, SYS_AREA
        ld hl, RESULTS          ; three bytes in the RAM, for the
        ld (hl), $5A            ; instructions that write
        ld ix, RESULTS
        ld (ix+2), $A5
t0:     and b
t1:     or $0f
t2:     xor (hl)
t3:     cpl
t4:     scf
t5:     ccf
t6:     bit 3, a
t7:     set 3, a
t8:     bit 3, (hl)
t9:     set 3, (hl)
t10:    res 3, (ix+2)
t11:    rlca
t12:    rrca
t13:    rla
t14:    rra
t15:    rlc a
t16:    rrc a
t17:    rl a
t18:    rr a
t19:    sla a
t20:    sra a
t21:    srl a
t22:    sll a
t23:    sra (hl)
t24:    rld
t25:    rrd
t26:
stop:   jr stop
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
